package com.fixflow.mall.service;

import com.fixflow.mall.api.dto.CreateOrderRequest;
import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.repo.OrderRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    private CreateOrderRequest validRequest;
    private List<Long> itemIds;

    @BeforeEach
    void setUp() {
        itemIds = Arrays.asList(101L, 102L);
        validRequest = new CreateOrderRequest();
        validRequest.setUserId(1L);
        validRequest.setAmount(new BigDecimal("50.00"));
        validRequest.setItemIds(itemIds);

        // Mock the repository save to return the saved entity
        when(orderRepository.save(any(MallOrder.class))).thenAnswer(invocation -> {
            MallOrder savedOrder = invocation.getArgument(0);
            savedOrder.setId(1L); // Simulate setting an ID after save
            return savedOrder;
        });
    }

    @Test
    @DisplayName("正向测试: 正常金额应成功创建订单并返回正确属性")
    void createOrder_withValidAmount_shouldReturnSavedOrder() {
        // Act
        MallOrder result = orderService.createOrder(validRequest);

        // Assert
        assertNotNull(result);
        assertEquals(validRequest.getUserId(), result.getUserId());
        assertEquals(validRequest.getAmount(), result.getAmount());
        assertEquals(validRequest.getItemIds(), result.getItemIds());
        assertEquals(1L, result.getId());
    }

    @Test
    @DisplayName("边界测试: 原修复的null金额输入不应抛出NullPointerException，而应抛出IllegalArgumentException")
    void createOrder_withNullAmount_shouldThrowIllegalArgumentExceptionAndNotNPE() {
        // Arrange
        CreateOrderRequest nullAmountRequest = new CreateOrderRequest();
        nullAmountRequest.setUserId(2L);
        nullAmountRequest.setAmount(null);
        nullAmountRequest.setItemIds(itemIds);

        // Act & Assert
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            orderService.createOrder(nullAmountRequest);
        });
        assertEquals("amount must > 0", exception.getMessage());
    }

    @Test
    @DisplayName("验证修复后的空值/null处理: 零金额应被正确拒绝")
    void createOrder_withZeroAmount_shouldThrowIllegalArgumentException() {
        // Arrange
        CreateOrderRequest zeroAmountRequest = new CreateOrderRequest();
        zeroAmountRequest.setUserId(3L);
        zeroAmountRequest.setAmount(BigDecimal.ZERO);
        zeroAmountRequest.setItemIds(itemIds);

        // Act & Assert
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            orderService.createOrder(zeroAmountRequest);
        });
        assertEquals("amount must > 0", exception.getMessage());
    }

    @Test
    @DisplayName("验证修复后的空值/null处理: 负金额应被正确拒绝")
    void createOrder_withNegativeAmount_shouldThrowIllegalArgumentException() {
        // Arrange
        CreateOrderRequest negativeAmountRequest = new CreateOrderRequest();
        negativeAmountRequest.setUserId(4L);
        negativeAmountRequest.setAmount(new BigDecimal("-10.00"));
        negativeAmountRequest.setItemIds(itemIds);

        // Act & Assert
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            orderService.createOrder(negativeAmountRequest);
        });
        assertEquals("amount must > 0", exception.getMessage());
    }
}
